namespace NovaHarvest.Core.Systems; public enum TimeOfDay{Day,Night} public sealed class WorldTime { public const int DayStartHour=4,DayStartMinute=30,NightStartHour=19,NightStartMinute=30; public int Day{get;private set;}=1;public int Hour{get;private set;}=8;public int Minute{get;private set;}=0;public TimeOfDay CurrentPeriod=>IsNight()?TimeOfDay.Night:TimeOfDay.Day; public event Action? DayStarted;public event Action? NightStarted;public event Action? NewDay; public bool IsNight(){if(Hour>=NightStartHour)return Hour>NightStartHour||Minute>=NightStartMinute;if(Hour<DayStartHour)return true;return Hour==DayStartHour&&Minute<DayStartMinute;} public void AdvanceMinutes(int minutes){if(minutes<0)throw new ArgumentOutOfRangeException(nameof(minutes));for(int i=0;i<minutes;i++){var before=CurrentPeriod;Minute++;if(Minute>=60){Minute=0;Hour++;}if(Hour>=24){Hour=0;Day++;NewDay?.Invoke();}var after=CurrentPeriod;if(before!=after){if(after==TimeOfDay.Night)NightStarted?.Invoke();else DayStarted?.Invoke();}}} public void StartNextDay(){Day++;Hour=DayStartHour;Minute=DayStartMinute;DayStarted?.Invoke();NewDay?.Invoke();} public string GetFormattedTime()=>$"{Hour:00}:{Minute:00}"; }
